import SuperJSON from './src/index.js';
import { parsePath, escapeKey } from './src/pathstringifier.js';

// Test 1: Basic round-trip with Set
console.log('=== Test 1: Basic Set round-trip ===');
try {
  const obj = { a: new Set([1, 2]) };
  const s = SuperJSON.stringify(obj);
  const p = SuperJSON.parse(s);
  console.log('PASS: basic Set round-trip');
} catch (e: any) {
  console.log('FAIL:', e.message);
}

// Test 2: Round-trip with backslash key and Set
console.log('\n=== Test 2: Backslash key + Set round-trip ===');
try {
  const obj = { 'b\\': new Set([1, 2]) };
  const s = SuperJSON.stringify(obj);
  console.log('Serialized:', s);
  const p = SuperJSON.parse(s);
  console.log('PASS: backslash key + Set round-trip');
  console.log('Result:', p);
} catch (e: any) {
  console.log('FAIL:', e.message);
}

// Test 3: parsePath legacy mode
console.log('\n=== Test 3: parsePath legacy mode ===');
try {
  const result = parsePath('test\\\\.a.b', true);
  console.log('Result:', result);
  console.log('Expected:', ['test\\.a', 'b']);
  const match = JSON.stringify(result) === JSON.stringify(['test\\.a', 'b']);
  console.log(match ? 'PASS' : 'FAIL');
} catch (e: any) {
  console.log('FAIL:', e.message);
}

// Test 4: parsePath non-legacy mode
console.log('\n=== Test 4: parsePath non-legacy mode ===');
try {
  const result = parsePath('test\\\\.a.b', false);
  console.log('Result:', result);
  console.log('Expected:', ['test\\\\', 'a', 'b']);
  const match = JSON.stringify(result) === JSON.stringify(['test\\\\', 'a', 'b']);
  console.log(match ? 'PASS' : 'FAIL');
} catch (e: any) {
  console.log('FAIL:', e.message);
}

// Test 5: parsePath non-legacy rejects invalid escapes
console.log('\n=== Test 5: parsePath rejects invalid escapes ===');
try {
  parsePath('test\\a.b', false);
