export type StringifiedPath = string;
type Path = string[];

export const escapeKey = (key: string, legacy = true) =>
  legacy
    ? key.replace(/\./g, '\\.')
    : key.replace(/\\/g, '\\\\').replace(/\./g, '\\.');

export const stringifyPath = (path: Path, legacy = true): StringifiedPath =>
  path
    .map(String)
    .map(k => escapeKey(k, legacy))
    .join('.');

export const parsePath = (
  string: StringifiedPath,
  legacy = true
): string[] => {
  const result: string[] = [];

  let segment = '';
  for (let i = 0; i < string.length; i++) {
    let char = string.charAt(i);

    if (char === '\\') {
      const next = string.charAt(i + 1);
      // Both modes: \. is escaped dot
      if (next === '.') {
        segment += '.';
        i++;
        continue;
      }
      // Non-legacy: \\ is escaped backslash (produces single \)
      if (!legacy && next === '\\') {
        segment += '\\';
        i++;
        continue;
      }
      // Non-legacy: \ followed by anything else is an error
      if (!legacy) {
        throw new Error(
          `Invalid backslash-escape in path: \\${next || '(end of string)'}`
        );
      }
      // Legacy: just a literal backslash
      segment += char;
      continue;
    }

    const isEndOfSegment = char === '.';
    if (isEndOfSegment) {
      result.push(segment);
      segment = '';
      continue;
    }

    segment += char;
  }

  const lastSegment = segment;
  result.push(lastSegment);

  return result;
};

