import { describe, it, expect } from 'vitest';
import SuperJSON from '../src/index.js';
import { parsePath, escapeKey, stringifyPath } from '../src/pathstringifier.js';
import { generateBoundaryInputs } from './fuzz-helpers.js';

describe('pathstringifier invariants', () => {
  // escapeKey must always produce a string parseable by parsePath
  describe('escapeKey ↔ parsePath round-trip', () => {
    const keys = [
      '',
      'a',
      '.',
      '..',
      '...',
      '\\',
      '\\\\',
      '\\.',
      '.\\',
      'a.b',
      'a\\b',
      'a.b\\c',
      '\\.a',
      'a\\.',
      '\\.\\.\\.',
      'test',
      'hello world',
      '\n',
      '\t',
      '',
      '\0',
      'key with spaces',
      'key.with.multiple.dots',
      '\\\\\\.\\\\\\',
      'a\\\\b',
    ];

    for (const key of keys) {
      it(`round-trips key ${JSON.stringify(key)} in legacy mode`, () => {
        const escaped = escapeKey(key, true);
        const parsed = parsePath(escaped, true);
        expect(parsed).toEqual([key]);
      });

      it(`round-trips key ${JSON.stringify(key)} in non-legacy mode`, () => {
        const escaped = escapeKey(key, false);
        const parsed = parsePath(escaped, false);
        expect(parsed).toEqual([key]);
      });
    }
  });

  describe('stringifyPath ↔ parsePath round-trip', () => {
    const paths = [
      ['a'],
      ['a', 'b'],
      ['a.b', 'c'],
      ['a\\b', 'c'],
      ['a', 'b.c'],
      ['a\\', 'b'],
      ['\\', 'a'],
      ['.', 'a'],
      ['a', '.'],
      ['', 'a'],
      ['a', ''],
      ['a', '', 'b'],
    ];

    for (const path of paths) {
      it(`round-trips path ${JSON.stringify(path)} in legacy mode`, () => {
        const stringified = stringifyPath(path, true);
        const parsed = parsePath(stringified, true);
        expect(parsed).toEqual(path);
      });

      it(`round-trips path ${JSON.stringify(path)} in non-legacy mode`, () => {
        const stringified = stringifyPath(path, false);
        const parsed = parsePath(stringified, false);
        expect(parsed).toEqual(path);
      });
    }
  });

  describe('parsePath error invariants', () => {
    it('rejects lone backslash at end in non-legacy', () => {
      expect(() => parsePath('foo\\', false)).toThrow();
    });

    it('rejects backslash followed by non-dot non-backslash in non-legacy', () => {
      expect(() => parsePath('a\\b', false)).toThrow();
      expect(() => parsePath('a\\c', false)).toThrow();
      expect(() => parsePath('a\\X', false)).toThrow();
    });

    it('does NOT reject in legacy mode', () => {
      expect(() => parsePath('foo\\', true)).not.toThrow();
      expect(() => parsePath('a\\b', true)).not.toThrow();
    });
  });
});

describe('SuperJSON round-trip invariants', () => {
  describe('backslash keys round-trip', () => {
    const keysWithBackslashes = [
      '\\',
      '\\\\',
      'a\\',
      '\\a',
      'a\\b',
      'a\\\\b',
      '\\.',
      '.\\',
    ];

    for (const key of keysWithBackslashes) {
      it(`round-trips key ${JSON.stringify(key)} with primitive value`, () => {
        const obj = { [key]: 42 };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p).toEqual(obj);
      });

      it(`round-trips key ${JSON.stringify(key)} with Set value`, () => {
        const obj = { [key]: new Set([1, 2, 3]) };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p).toEqual(obj);
      });

      it(`round-trips key ${JSON.stringify(key)} with RegExp value`, () => {
        const obj = { [key]: /test/g };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p[key].source).toBe('test');
        expect(p[key].flags).toBe('g');
      });

      it(`round-trips key ${JSON.stringify(key)} with Date value`, () => {
        const date = new Date('2024-01-15T12:00:00Z');
        const obj = { [key]: date };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p[key]).toEqual(date);
      });
    }
  });

  describe('dot keys round-trip', () => {
    const keysWithDots = [
      '.',
      '..',
      '...',
      'a.b',
      'a.b.c',
      'key.with.many.dots',
    ];

    for (const key of keysWithDots) {
      it(`round-trips key ${JSON.stringify(key)} with Set value`, () => {
        const obj = { [key]: new Set([1, 2]) };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p).toEqual(obj);
      });
    }
  });

  describe('combined backslash and dot keys round-trip', () => {
    const keys = [
      'a\\.b',
      '\\.a',
      'a\\.',
      '\\\\.',
      '.\\\\',
    ];

    for (const key of keys) {
      it(`round-trips key ${JSON.stringify(key)} with Set value`, () => {
        const obj = { [key]: new Set([1, 2]) };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p).toEqual(obj);
      });
    }
  });

  describe('nested objects with special keys', () => {
    it('round-trips nested object with backslash keys', () => {
      const obj = {
        'a\\': {
          b: new Set([1, 2]),
        },
      };
      const s = SuperJSON.stringify(obj);
      const p = SuperJSON.parse(s);
      expect(p).toEqual(obj);
    });

    it('round-trips deeply nested objects with dot keys', () => {
      const obj = {
        'a.b': {
          'c.d': new Set([1, 2]),
        },
      };
      const s = SuperJSON.stringify(obj);
      const p = SuperJSON.parse(s);
      expect(p).toEqual(obj);
    });
  });

  describe('backward compatibility', () => {
    it('deserializes legacy format without v marker', () => {
      const result = SuperJSON.deserialize({
        json: { 'a.1': { b: [1, 2] } },
        meta: { values: { 'a\\.1.b': ['set'] } },
      });
      expect(result).toEqual({ 'a.1': { b: new Set([1, 2]) } });
    });

    it('deserializes legacy format with backslash paths', () => {
      const result = SuperJSON.deserialize({
        json: { 'a\\.1': { b: [1, 2] } },
        meta: { values: { 'a\\\\.1.b': ['set'] } },
      });
      expect(result).toEqual({ 'a\\.1': { b: new Set([1, 2]) } });
    });
  });

  describe('boundary conditions', () => {
    for (const input of generateBoundaryInputs()) {
      it(`round-trips ${JSON.stringify(input)} as value`, () => {
        const obj = { key: input };
        try {
          const s = SuperJSON.stringify(obj);
          const p = SuperJSON.parse(s);
          expect(p.key).toEqual(input);
        } catch (e) {
          // Some values may not be serializable (e.g., functions)
          // That's acceptable
        }
      });
    }
  });

  describe('meta.v marker', () => {
    it('sets v=2 when there are annotations', () => {
      const obj = { a: new Set([1]) };
      const result = SuperJSON.serialize(obj);
      expect(result.meta).toBeDefined();
      expect((result.meta as any).v).toBe(2);
    });

    it('does not set v when no annotations needed', () => {
      const obj = { a: 1 };
      const result = SuperJSON.serialize(obj);
      // meta may or may not exist, but if it does, v should be 2
      if (result.meta) {
        expect((result.meta as any).v).toBe(2);
      }
    });
  });
});

