import SuperJSON from './src/index.js';
import { parsePath, escapeKey } from './src/pathstringifier.js';

let failures = 0;
function check(name: string, actual: any, expected: any) {
  // Deep comparison that handles regex, dates, etc.
  const pass = JSON.stringify(actual) === JSON.stringify(expected)
    || deepEqual(actual, expected);
  console.log(`${pass ? 'PASS' : 'FAIL'}: ${name}`);
  if (!pass) {
    console.log(`  Got: ${JSON.stringify(actual)}`);
    console.log(`  Expected: ${JSON.stringify(expected)}`);
    failures++;
  }
}

function deepEqual(a: any, b: any): boolean {
  if (a === b) return true;
  if (a instanceof RegExp && b instanceof RegExp) return a.source === b.source && a.flags === b.flags;
  if (a instanceof Date && b instanceof Date) return a.getTime() === b.getTime();
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    for (const v of a) { if (!b.has(v)) return false; }
    return true;
  }
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [k, v] of a) { if (!deepEqual(v, b.get(k))) return false; }
    return true;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    return a.every((v, i) => deepEqual(v, b[i]));
  }
  if (a && b && typeof a === 'object' && typeof b === 'object') {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    return keysA.every(k => deepEqual(a[k], b[k]));
  }
  return false;
}

// Test 1: Basic round-trip with Set
console.log('=== Test 1: Basic Set round-trip ===');
try {
  const obj = { a: new Set([1, 2]) };
  const s = SuperJSON.stringify(obj);
  const p = SuperJSON.parse(s);
  check('basic Set round-trip', p, obj);
} catch (e: any) {
  console.log('FAIL: exception:', e.message);
  failures++;
}

// Test 2: Round-trip with backslash key and Set
console.log('\n=== Test 2: Backslash key + Set round-trip ===');
try {
  const obj = { 'b\\': new Set([1, 2]) };
  const s = SuperJSON.stringify(obj);
  const p = SuperJSON.parse(s);
  check('backslash key + Set round-trip', p, obj);
} catch (e: any) {
  console.log('FAIL: exception:', e.message);
  failures++;
}

// Test 3: Round-trip with dot key and Set
console.log('\n=== Test 3: Dot key + Set round-trip ===');
try {
  const obj = { 'a.1': { b: new Set([1, 2]) } };
  const s = SuperJSON.stringify(obj);
  const p = SuperJSON.parse(s);
  check('dot key + Set round-trip', p, obj);
} catch (e: any) {
  console.log('FAIL: exception:', e.message);
  failures++;
}

// Test 4: parsePath legacy mode
console.log('\n=== Test 4: parsePath legacy mode ===');
check('legacy basic', parsePath('test.a.b', true), ['test', 'a', 'b']);
check('legacy escaped dot', parsePath('test\\.a.b', true), ['test.a', 'b']);
check('legacy double backslash + dot', parsePath('test\\\\.a.b', true), ['test\\.a', 'b']);

// Test 5: parsePath non-legacy mode
console.log('\n=== Test 5: parsePath non-legacy mode ===');
check('non-legacy basic', parsePath('test.a.b', false), ['test', 'a', 'b']);
check('non-legacy escaped dot', parsePath('test\\.a.b', false), ['test.a', 'b']);
check('non-legacy escaped backslash + dot', parsePath('test\\\\.a.b', false), ['test\\', 'a', 'b']);
check('non-legacy escaped backslash', parsePath('test\\\\a.b', false), ['test\\a', 'b']);

// Test 6: parsePath non-legacy rejects
console.log('\n=== Test 6: parsePath rejects invalid escapes ===');
try {
  parsePath('test\\a.b', false);
  console.log('FAIL: should have thrown for \\a');
  failures++;
} catch {
  console.log('PASS: correctly threw for \\a');
}
try {
  parsePath('foo.bar.baz\\', false);
  console.log('FAIL: should have thrown for trailing \\');
  failures++;
} catch {
  console.log('PASS: correctly threw for trailing \\');
}

// Test 7: escapeKey with backslash
console.log('\n=== Test 7: escapeKey ===');
check('escapeKey backslash (non-legacy)', escapeKey('b\\', false), 'b\\\\');
check('escapeKey backslash in middle (non-legacy)', escapeKey('a\\b', false), 'a\\\\b');
check('escapeKey dot (non-legacy)', escapeKey('a.b', false), 'a\\.b');

// Test 8: meta.v version marker
console.log('\n=== Test 8: meta.v version marker ===');
try {
  const obj = { a: new Date() };
  const serialized = SuperJSON.serialize(obj);
  check('meta.v present', (serialized.meta as any)?.v, 2);
} catch (e: any) {
  console.log('FAIL:', e.message);
  failures++;
}

// Test 9: Backward compat — deserialize old format (legacy)
console.log('\n=== Test 9: Backward compat (legacy deserialization) ===');
try {
  const result = SuperJSON.deserialize({
    json: { 'a.1': { b: [1, 2] } },
    meta: { values: { 'a\\.1.b': ['set'] } },
  });
  check('legacy backward compat', result, { 'a.1': { b: new Set([1, 2]) } });
} catch (e: any) {
  console.log('FAIL:', e.message);
  failures++;
}

// Test 10: Repro #310 - backslash key with RegExp
console.log('\n=== Test 10: Repro #310 ===');
try {
  const obj = {
    a: ["/'a'[0]: string that becomes a regex/"],
    'a.0': /'a.0': regex that becomes a string/,
    'b.0': "/'b.0': string that becomes a regex/",
    'b\\': [/'b\\'[0]: regex that becomes a string/],
  };
  const s = SuperJSON.stringify(obj);
  const p = SuperJSON.parse(s);
  check('repro #310 round-trip', p, {
    a: ["/'a'[0]: string that becomes a regex/"],
    'a.0': /'a.0': regex that becomes a string/,
    'b.0': "/'b.0': string that becomes a regex/",
    'b\\': [/'b\\'[0]: regex that becomes a string/],
  });
} catch (e: any) {
  console.log('FAIL:', e.message);
  failures++;
}

console.log(`\n=== Results: ${failures} failures ===`);
process.exit(failures > 0 ? 1 : 0);

import { describe, it, expect } from 'vitest';
import SuperJSON from '../src/index.js';
import { parsePath, escapeKey, stringifyPath } from '../src/pathstringifier.js';
import { generateBoundaryInputs } from './fuzz-helpers.js';

describe('pathstringifier invariants', () => {
  // escapeKey must always produce a string parseable by parsePath
  describe('escapeKey ↔ parsePath round-trip', () => {
    const keys = [
      '',
      'a',
      '.',
      '..',
      '...',
      '\\',
      '\\\\',
      '\\.',
      '.\\',
      'a.b',
      'a\\b',
      'a.b\\c',
      '\\.a',
      'a\\.',
      '\\.\\.\\.',
      'test',
      'hello world',
      '\n',
      '\t',
      '',
      '\0',
      'key with spaces',
      'key.with.multiple.dots',
      '\\\\\\.\\\\\\',
      'a\\\\b',
    ];

    for (const key of keys) {
      it(`round-trips key ${JSON.stringify(key)} in legacy mode`, () => {
        const escaped = escapeKey(key, true);
        const parsed = parsePath(escaped, true);
        expect(parsed).toEqual([key]);
      });

      it(`round-trips key ${JSON.stringify(key)} in non-legacy mode`, () => {
        const escaped = escapeKey(key, false);
        const parsed = parsePath(escaped, false);
        expect(parsed).toEqual([key]);
      });
    }
  });

  describe('stringifyPath ↔ parsePath round-trip', () => {
    const paths = [
      ['a'],
      ['a', 'b'],
      ['a.b', 'c'],
      ['a\\b', 'c'],
      ['a', 'b.c'],
      ['a\\', 'b'],
      ['\\', 'a'],
      ['.', 'a'],
      ['a', '.'],
      ['', 'a'],
      ['a', ''],
      ['a', '', 'b'],
    ];

    for (const path of paths) {
      it(`round-trips path ${JSON.stringify(path)} in legacy mode`, () => {
        const stringified = stringifyPath(path, true);
        const parsed = parsePath(stringified, true);
        expect(parsed).toEqual(path);
      });

      it(`round-trips path ${JSON.stringify(path)} in non-legacy mode`, () => {
        const stringified = stringifyPath(path, false);
        const parsed = parsePath(stringified, false);
        expect(parsed).toEqual(path);
      });
    }
  });

  describe('parsePath error invariants', () => {
    it('rejects lone backslash at end in non-legacy', () => {
      expect(() => parsePath('foo\\', false)).toThrow();
    });

    it('rejects backslash followed by non-dot non-backslash in non-legacy', () => {
      expect(() => parsePath('a\\b', false)).toThrow();
      expect(() => parsePath('a\\c', false)).toThrow();
      expect(() => parsePath('a\\X', false)).toThrow();
    });

    it('does NOT reject in legacy mode', () => {
      expect(() => parsePath('foo\\', true)).not.toThrow();
      expect(() => parsePath('a\\b', true)).not.toThrow();
    });
  });
});

describe('SuperJSON round-trip invariants', () => {
  describe('backslash keys round-trip', () => {
    const keysWithBackslashes = [
      '\\',
      '\\\\',
      'a\\',
      '\\a',
      'a\\b',
      'a\\\\b',
      '\\.',
      '.\\',
    ];

    for (const key of keysWithBackslashes) {
      it(`round-trips key ${JSON.stringify(key)} with primitive value`, () => {
        const obj = { [key]: 42 };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p).toEqual(obj);
      });

      it(`round-trips key ${JSON.stringify(key)} with Set value`, () => {
        const obj = { [key]: new Set([1, 2, 3]) };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p).toEqual(obj);
      });

      it(`round-trips key ${JSON.stringify(key)} with RegExp value`, () => {
        const obj = { [key]: /test/g };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p[key].source).toBe('test');
        expect(p[key].flags).toBe('g');
      });

      it(`round-trips key ${JSON.stringify(key)} with Date value`, () => {
        const date = new Date('2024-01-15T12:00:00Z');
        const obj = { [key]: date };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p[key]).toEqual(date);
      });
    }
  });

  describe('dot keys round-trip', () => {
    const keysWithDots = [
      '.',
      '..',
      '...',
      'a.b',
      'a.b.c',
      'key.with.many.dots',
    ];

    for (const key of keysWithDots) {
      it(`round-trips key ${JSON.stringify(key)} with Set value`, () => {
        const obj = { [key]: new Set([1, 2]) };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p).toEqual(obj);
      });
    }
  });

  describe('combined backslash and dot keys round-trip', () => {
    const keys = [
      'a\\.b',
      '\\.a',
      'a\\.',
      '\\\\.',
      '.\\\\',
    ];

    for (const key of keys) {
      it(`round-trips key ${JSON.stringify(key)} with Set value`, () => {
        const obj = { [key]: new Set([1, 2]) };
        const s = SuperJSON.stringify(obj);
        const p = SuperJSON.parse(s);
        expect(p).toEqual(obj);
      });
    }
  });

  describe('nested objects with special keys', () => {
    it('round-trips nested object with backslash keys', () => {
      const obj = {
        'a\\': {
          b: new Set([1, 2]),
        },
      };
      const s = SuperJSON.stringify(obj);
      const p = SuperJSON.parse(s);
      expect(p).toEqual(obj);
    });

    it('round-trips deeply nested objects with dot keys', () => {
      const obj = {
        'a.b': {
          'c.d': new Set([1, 2]),
        },
      };
      const s = SuperJSON.stringify(obj);
      const p = SuperJSON.parse(s);
      expect(p).toEqual(obj);
    });
  });

  describe('backward compatibility', () => {
    it('deserializes legacy format without v marker', () => {
      const result = SuperJSON.deserialize({
        json: { 'a.1': { b: [1, 2] } },
        meta: { values: { 'a\\.1.b': ['set'] } },
      });
      expect(result).toEqual({ 'a.1': { b: new Set([1, 2]) } });
    });

    it('deserializes legacy format with backslash paths', () => {
      const result = SuperJSON.deserialize({
        json: { 'a\\.1': { b: [1, 2] } },
        meta: { values: { 'a\\\\.1.b': ['set'] } },
      });
      expect(result).toEqual({ 'a\\.1': { b: new Set([1, 2]) } });
    });
  });

  describe('boundary conditions', () => {
    for (const input of generateBoundaryInputs()) {
      it(`round-trips ${JSON.stringify(input)} as value`, () => {
        const obj = { key: input };
        try {
          const s = SuperJSON.stringify(obj);
          const p = SuperJSON.parse(s);
          expect(p.key).toEqual(input);
        } catch (e) {
          // Some values may not be serializable (e.g., functions)
          // That's acceptable
        }
      });
    }
  });

  describe('meta.v marker', () => {
    it('sets v=2 when there are annotations', () => {
      const obj = { a: new Set([1]) };
      const result = SuperJSON.serialize(obj);
      expect(result.meta).toBeDefined();
      expect((result.meta as any).v).toBe(2);
    });

    it('does not set v when no annotations needed', () => {
      const obj = { a: 1 };
      const result = SuperJSON.serialize(obj);
      // meta may or may not exist, but if it does, v should be 2
      if (result.meta) {
        expect((result.meta as any).v).toBe(2);
      }
    });
  });
});

